O resultado final do referido algoritmo é 16. No que se refere aos conceitos de ordenamento, julgue o seguinte item.

public class Fruta { private double fvalor; private String fnome; Fruta(double fPreco, String fNome) {

fvalor = fPreco;

fnome = fNome; } Fruta(Fruta fruta) {

fvalor = fruta.fvalor;

fnome = fruta.fnome; } double showPreco() {

return fvalor; } String showNome() {

return fnome; } public static void main(String args[]) {

Fruta f1 = new Fruta(399, “Laranja Lima”);

System.out.println(“Nome da fruta 1: “+ f1.showNome());

System.out.println(“Preco da fruta 1: “+ f1.showPreco());

Fruta f2 = new Fruta(f1); System.out.println(“Nome da fruta 2: “+ f2.showNome());

System.out.println(“Preço da fruta 2: “+ f2.showPreco()); } }

